        Scanner sc = new Scanner(System.in);
        int v = sc.nextInt(), e = sc.nextInt();
        ArrayList<ArrayList<Integer>> g = new ArrayList<>();
        for (int i = 0; i < v; i++) g.add(new ArrayList<>());
        for (int i = 0; i < e; i++) {
            int u = sc.nextInt(), w = sc.nextInt();
            g.get(u).add(w);
            g.get(w).add(u);
        }
        int s = sc.nextInt(), t = sc.nextInt();
        System.out.println(minHops(g, s, t));
    }

    static int minHops(ArrayList<ArrayList<Integer>> g, int s, int t) {
        if (s == t) return 0;
        int[] dist = new int[g.size()];
        Arrays.fill(dist, -1);
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        dist[s] = 0;
        queue.add(s);
        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int w : g.get(u)) {
                if (dist[w] == -1) {
                    dist[w] = dist[u] + 1;
                    if (w == t) return dist[w];
                    queue.add(w);
                }
            }
        }
        return -1;
    }
}

