    static int hasCycle(ArrayList<ArrayList<Integer>> g) {
        int[] color = new int[g.size()];
        for (int s = 0; s < g.size(); s++) {
            if (color[s] == 0 && dfsCycle(g, s, color)) return 1;
        }
        return 0;
    }

    static boolean dfsCycle(ArrayList<ArrayList<Integer>> g, int u, int[] color) {
        color[u] = 1;
        for (int w : g.get(u)) {
            if (color[w] == 1) return true;
            if (color[w] == 0 && dfsCycle(g, w, color)) return true;
        }
        color[u] = 2;
        return false;
    }
}

