public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int v = sc.nextInt(), e = sc.nextInt();
        int[][] edges = new int[e][2];
        for (int i = 0; i < e; i++) {
            edges[i][0] = sc.nextInt();
            edges[i][1] = sc.nextInt();
        }
        int q = sc.nextInt();
        int[][] queries = new int[q][2];
        for (int i = 0; i < q; i++) {
            queries[i][0] = sc.nextInt();
            queries[i][1] = sc.nextInt();
        }
        String[] ans = connectivityQueries(v, edges, queries);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < ans.length; i++) {
            if (i > 0) sb.append('\n');
            sb.append(ans[i]);
        }
        so.println(sb);
    }

    static String[] connectivityQueries(int v, int[][] edges, int[][] queries) {
        int[] parent = new int[v];
        for (int i = 0; i < v; i++) parent[i] = i;
        for (int[] ed : edges) union(parent, ed[0], ed[1]);
        String[] ans = new String[queries.length];
        for (int i = 0; i < queries.length; i++) {
            ans[i] = find(parent, queries[i][0]) == find(parent, queries[i][1]) ? "YES" : "NO";
        }
        return ans;
    }

    static int find(int[] parent, int x) {
        while (parent[x] != x) x = parent[x];
        return x;
    }

    static void union(int[] parent, int a, int b) {
        parent[find(parent, a)] = find(parent, b);
    }
}

