    static int hasUndirectedCycle(ArrayList<ArrayList<Integer>> g) {
        boolean[] visited = new boolean[g.size()];
        for (int s = 0; s < g.size(); s++) {
            if (!visited[s] && cycleDfs(g, s, -1, visited)) return 1;
        }
        return 0;
    }

    static boolean cycleDfs(ArrayList<ArrayList<Integer>> g, int u, int parent, boolean[] visited) {
        visited[u] = true;
        for (int w : g.get(u)) {
            if (w == parent) continue;
            if (!visited[w]) {
                if (cycleDfs(g, w, u, visited)) return true;
            } else {
                return true;
            }
        }
        return false;
    }
}

