public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int v = sc.nextInt(), e = sc.nextInt();
        ArrayList<ArrayList<Integer>> g = new ArrayList<>();
        for (int i = 0; i < v; i++) g.add(new ArrayList<>());
        for (int i = 0; i < e; i++) {
            int u = sc.nextInt(), w = sc.nextInt();
            g.get(u).add(w);
        }
        so.println(longestChain(g));
    }

    static int longestChain(ArrayList<ArrayList<Integer>> g) {
        int v = g.size();
        int[] indeg = new int[v];
        for (ArrayList<Integer> nbrs : g) {
            for (int w : nbrs) indeg[w]++;
        }
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        int[] depth = new int[v];
        for (int i = 0; i < v; i++) {
            depth[i] = 1;
            if (indeg[i] == 0) queue.add(i);
        }
        int best = 0;
        while (!queue.isEmpty()) {
            int u = queue.poll();
            if (depth[u] > best) best = depth[u];
            for (int w : g.get(u)) {
                if (depth[u] + 1 > depth[w]) depth[w] = depth[u] + 1;
                indeg[w]--;
                if (indeg[w] == 0) queue.add(w);
            }
        }
        return best;
    }
}

