public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int v = sc.nextInt(), e = sc.nextInt();
        ArrayList<ArrayList<Integer>> g = new ArrayList<>();
        for (int i = 0; i < v; i++) g.add(new ArrayList<>());
        for (int i = 0; i < e; i++) {
            int u = sc.nextInt(), w = sc.nextInt();
            g.get(u).add(w);
        }
        so.println(joinArr(topoOrder(g)));
    }

    static String joinArr(int[] a) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < a.length; i++) {
            if (i > 0) sb.append(' ');
            sb.append(a[i]);
        }
        return sb.toString();
    }

    static int[] topoOrder(ArrayList<ArrayList<Integer>> g) {
        int v = g.size();
        int[] indeg = new int[v];
        for (ArrayList<Integer> nbrs : g) {
            for (int w : nbrs) indeg[w]++;
        }
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int i = 0; i < v; i++) {
            if (indeg[i] == 0) pq.add(i);
        }
        int[] order = new int[v];
        int idx = 0;
        while (!pq.isEmpty()) {
            int u = pq.poll();
            order[idx++] = u;
            for (int w : g.get(u)) {
                indeg[w]--;
                if (indeg[w] == 0) pq.add(w);
            }
        }
        return order;
    }
}

