public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int v = sc.nextInt();
        int[][] w = new int[v][v];
        for (int i = 0; i < v; i++) {
            for (int j = 0; j < v; j++) w[i][j] = sc.nextInt();
        }
        so.println(dijkstra(w));
    }

    static int dijkstra(int[][] w) {
        int v = w.length;
        int[] dist = new int[v];
        boolean[] visited = new boolean[v];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[0] = 0;
        for (int step = 0; step < v; step++) {
            int u = -1;
            for (int i = 0; i < v; i++) {
                if (!visited[i] && dist[i] != Integer.MAX_VALUE && (u == -1 || dist[i] < dist[u])) u = i;
            }
            if (u == -1) break;
            visited[u] = true;
            for (int j = 0; j < v; j++) {
                if (w[u][j] > 0 && dist[u] + w[u][j] < dist[j]) dist[j] = dist[u] + w[u][j];
            }
        }
        return dist[v - 1] == Integer.MAX_VALUE ? -1 : dist[v - 1];
    }
}

