            g.get(u).add(w);
            g.get(w).add(u);
        }
        so.println(isBipartite(g));
    }

    static int isBipartite(ArrayList<ArrayList<Integer>> g) {
        int v = g.size();
        int[] color = new int[v];
        for (int s = 0; s < v; s++) {
            if (color[s] != 0) continue;
            ArrayDeque<Integer> queue = new ArrayDeque<>();
            color[s] = 1;
            queue.add(s);
            while (!queue.isEmpty()) {
                int u = queue.poll();
                for (int w : g.get(u)) {
                    if (color[w] == 0) {
                        color[w] = -color[u];
                        queue.add(w);
                    } else if (color[w] == color[u]) {
                        return 0;
                    }
                }
            }
        }
        return 1;
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        java.io.PrintStream so = System.out;
        Scanner sc = new Scanner(System.in);
        int r = sc.nextInt(), c = sc.nextInt();
        char[][] grid = new char[r][];
        for (int i = 0; i < r; i++) grid[i] = sc.next().toCharArray();
        so.println(islandCount(grid));
    }

    static int islandCount(char[][] grid) {
        int r = grid.length;
        int c = grid[0].length;
        boolean[][] visited = new boolean[r][c];
        int count = 0;
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                if (grid[i][j] == '1' && !visited[i][j]) {
                    count++;
                    sink(grid, visited, i, j);
                }
            }
        }
        return count;
    }

    static void sink(char[][] grid, boolean[][] visited, int i, int j) {
        if (i < 0 || j < 0 || i >= grid.length || j >= grid[0].length) return;
        if (visited[i][j] || grid[i][j] != '1') return;
        visited[i][j] = true;
        sink(grid, visited, i + 1, j);
        sink(grid, visited, i - 1, j);
        sink(grid, visited, i, j + 1);
        sink(grid, visited, i, j - 1);
    }
}
